J root(const std::vector<m::MediaAssemblySurface>&plan){J::Array children;children.reserve(plan.size());for(const auto&s:plan)children.push_back(s.content);return J::Object{{"bounds",J::Array{0,0,440,440}},{"position",J::Array{0,0}},{"anchorPoint",J::Array{0,0}},{"children",std::move(children)}};}
bool valid(R r){return std::isfinite(r.x)&&std::isfinite(r.y)&&std::isfinite(r.width)&&std::isfinite(r.height)&&r.width>0&&r.height>0&&std::isfinite(r.x+r.width)&&std::isfinite(r.y+r.height);}
bool cutContains(R r,core::Point p){if(!r.contains(p))return false;const auto x=p.x-r.x,y=p.y-r.y,k=std::min(4.,std::min(r.width,r.height)/3);return x+y>=k&&x+y<=r.width+r.height-k;}
struct Track{double from{},target{},start{},duration{};double value(double time)const{return duration?from+(target-from)*easeOut((time-start)/duration):target;}bool active(double time)const noexcept{return duration&&from!=target&&time<start+duration;}};
M fit(const MediaAssemblyPreviewDraw&v,R rect){need(valid(v.sourceBounds)&&valid(rect),"Invalid borrowed Media Assembly image plane");return M::translation(rect.x,rect.y)*M::scale(rect.width/v.sourceBounds.width,rect.height/v.sourceBounds.height)*M::translation(-v.sourceBounds.x,-v.sourceBounds.y)*v.draw.world;}
