NativeMediaAssemblyScene::NativeMediaAssemblyScene(LayerRasterizer&r,LayerRasterOptions o,const NativeMediaAssemblyAssets&a):impl_(std::make_unique<Impl>(r,std::move(o),a)){}
NativeMediaAssemblyScene::~NativeMediaAssemblyScene()=default;
bool NativeMediaAssemblyScene::syncContent(const m::MediaAssemblyPresentation&p,const m::MediaAssemblyView&v,const m::MediaAssemblyAppearance&a,std::string_view error,double progress,double time,bool animateInline,bool reduced){auto&i=*impl_;i.clock(time);auto art=m::prepareMediaAssemblyArtwork(p,v,a,i.assets,error,progress);std::array<std::vector<m::MediaAssemblySurface>,groups>plans;for(auto&s:art.surfaces)plans[std::size_t(s.group)].push_back(std::move(s));std::array<std::unique_ptr<Impl::Part>,groups>replacements;for(std::size_t k=0;k<groups;++k)if(!plans[k].empty()&&(!i.parts[k]||!i.parts[k]->sameShape(plans[k])))replacements[k]=std::make_unique<Impl::Part>(i.raster,std::move(plans[k]),i.options,G(k));bool changed=i.image!=art.imageRect;for(std::size_t k=0;k<groups;++k){auto&old=i.parts[k];if(replacements[k]||plans[k].empty()){if(replacements[k]||old){i.retire(std::move(old));old=std::move(replacements[k]);changed=true;++i.statistics.builds;}continue;}auto&part=*old;if(part.scene.fontRevision()!=i.raster.fontRevision()){changed=part.scene.refreshTypography()||changed;}for(std::size_t n=0;n<plans[k].size();++n){auto&next=plans[k][n];auto&before=part.plan[n];if(before.content!=next.content){need(part.localRevisions[n]!=UINT64_MAX,"Media Assembly local revision exhausted");part.scene.updateLocalContent(before.id,++part.localRevisions[n],next.content,i.options);++i.statistics.localUpdates;changed=true;}if(before.local!=next.local||before.clips!=next.clips||before.opacity!=next.opacity||before.feedbackEnabled!=next.feedbackEnabled)changed=true;before=std::move(next);}}
 i.image=art.imageRect;if(i.targetOffset!=p.drawerOffset()){i.motion.scrollInline(p.drawerOffset(),time,animateInline&&!reduced);i.targetOffset=p.drawerOffset();changed=true;}i.time=time;i.feedbackDirty|=changed;i.reduced=reduced;setFeedback(i.pointer,i.pressed,reduced,time);return changed;}
void NativeMediaAssemblyScene::setPreview(std::optional<MediaAssemblyPreviewDraw>draw){auto&i=*impl_;if(draw){checkPreview(*draw);auto next=draw->draw;next.masks.reserve(8);i.previewOutput[0]=std::move(next);}i.preview=std::move(draw);if(i.posed)i.posePreview();i.refresh();}
void NativeMediaAssemblyScene::revealDrawer(double time,bool animated){auto&i=*impl_;i.clock(time);i.motion.revealDrawer(time,animated);i.time=time;}
void NativeMediaAssemblyScene::beginClose(std::optional<MediaAssemblyPreviewDraw>poster,double time,bool animated){auto&i=*impl_;i.clock(time);if(poster)checkPreview(*poster);std::unique_ptr<Impl::Closing>next;if(poster&&animated){need(valid(i.image),"Synchronize Media Assembly image before closing");next=std::make_unique<Impl::Closing>(i.raster,std::move(*poster),i.image);}i.retireClosing();if(next){next->stickers=std::move(i.parts[std::size_t(G::stickers)]);i.closing=std::move(next);}i.preview.reset();i.motion.closeMedia(time,bool(i.closing));i.time=time;i.refresh();}
