bool NativeMediaAssemblyScene::setFeedback(std::optional<core::Point>point,bool pressed,bool reduced,double time){auto&i=*impl_;i.clock(time);if(point)need(std::isfinite(point->x)&&std::isfinite(point->y),"Invalid Media Assembly pointer");if(!i.feedbackDirty&&i.pointer==point&&i.pressed==pressed&&i.reduced==reduced)return false;std::string_view action;double area=INFINITY;if(point)for(auto&p:i.parts)if(p)for(const auto&s:p->plan)if(s.role==Role::tint&&s.feedbackEnabled){const auto&b=s.content["bounds"].array();R rect{s.local.values[12],s.local.values[13],b[2].number(),b[3].number()};bool inside=cutContains(rect,*point);for(std::size_t k=0;k<s.clipCount;++k)inside&=s.clips[k].bounds.contains(*point);if(inside&&rect.width*rect.height<=area){action=s.action;area=rect.width*rect.height;}}
 for(auto&p:i.parts)if(p)for(std::size_t n=0;n<p->plan.size();++n){const auto&s=p->plan[n];if(s.role!=Role::tint&&s.role!=Role::rim)continue;const bool match=s.feedbackEnabled&&s.action==action;const double target=match?(s.role==Role::rim?1:pressed?1:.62):(s.role==Role::rim&&s.feedbackEnabled&&s.framed?.28:0);auto&t=p->tracks[n];if(t.target!=target||(reduced&&t.duration))t={t.value(time),target,time,reduced?0:pressed&&match?.06:.14};}i.pointer=point;i.pressed=pressed;i.reduced=reduced;i.feedbackDirty=false;i.time=time;return true;}
void NativeMediaAssemblyScene::updatePose(const MediaAssemblyScenePose&p){auto&i=*impl_;i.clock(p.time);need(p.world.finite()&&std::isfinite(p.opacity)&&p.opacity>=0&&p.opacity<=1&&p.ownerMasks.size()<=6,"Invalid Media Assembly pose");(void)core::source::inverseSourceMatrix(p.world);if(p.shutter)validatePlaneShutter(*p.shutter);for(const auto&mask:p.ownerMasks)need(mask.worldToLocal.finite()&&valid(mask.bounds)&&std::isfinite(mask.cornerRadius)&&mask.cornerRadius>=0&&mask.cornerRadius<=std::min(mask.bounds.width,mask.bounds.height)*.5,"Invalid Media Assembly owner mask");i.world=p.world;i.opacity=p.opacity;i.time=p.time;i.ownerMaskCount=p.ownerMasks.size();std::copy(p.ownerMasks.begin(),p.ownerMasks.end(),i.ownerMasks.begin());i.shutter=p.shutter?std::optional(*p.shutter):std::nullopt;for(std::size_t k=0;k<groups;++k)if(i.parts[k])i.posePart(*i.parts[k],k==std::size_t(G::drawer));i.posePreview();if(i.closing&&i.motion.closeOpacity(p.time)==0)i.retireClosing();i.poseGroups();i.posed=true;i.refresh();++i.statistics.poses;}
